package api

import (
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
)

var scopeRouteDeclRe = regexp.MustCompile(`mux\.Handle(?:Func)?\("([A-Z]+)\s+([^"]*)"((?:\s*\+\s*(?:\w+|"[^"]*"))*)\s*,\s*(.*)$`)

var scopeRoutePartRe = regexp.MustCompile(`\+\s*(?:(\w+)|"([^"]*)")`)

// loadUnscopedParamRoutes returns every literal route with a {param} segment
// that is not wrapped in requireAbilityForResource, keyed "METHOD path".
func loadUnscopedParamRoutes(t *testing.T) map[string]bool {
	t.Helper()
	files, err := filepath.Glob("*.go")
	if err != nil || len(files) == 0 {
		t.Fatalf("glob api sources: %v", err)
	}
	found := map[string]bool{}
	for _, f := range files {
		if strings.HasSuffix(f, "_test.go") {
			continue
		}
		src, err := os.ReadFile(f) //nolint:gosec // package-local glob
		if err != nil {
			t.Fatal(err)
		}
		lines := strings.Split(string(src), "\n")
		for i, line := range lines {
			if strings.HasPrefix(strings.TrimSpace(line), "//") {
				continue
			}
			m := scopeRouteDeclRe.FindStringSubmatch(line)
			if m == nil {
				continue
			}
			rest := m[4]
			for j := i + 1; j < len(lines) && j < i+4 && parenBalance(rest) > 0; j++ {
				rest += " " + strings.TrimSpace(lines[j])
			}
			path := m[2]
			for _, p := range scopeRoutePartRe.FindAllStringSubmatch(m[3], -1) {
				if p[1] != "" {
					path += "<" + p[1] + ">"
				} else {
					path += p[2]
				}
			}
			if !strings.Contains(path, "{") || strings.Contains(rest, "requireAbilityForResource(") {
				continue
			}
			found[m[1]+" "+path] = true
		}
	}
	return found
}

// TestParamRoutesAreScopedOrAllowlisted fails when a {param} route uses neither
// a ForResource wrapper nor an allowlist entry, and when an entry goes stale.
func TestParamRoutesAreScopedOrAllowlisted(t *testing.T) {
	found := loadUnscopedParamRoutes(t)
	if len(found) == 0 {
		t.Fatal("scanner found no unscoped param routes; it has stopped seeing the router")
	}
	var missing, stale []string
	for k := range found {
		if _, ok := paramRouteScopeAllowlist[k]; !ok {
			missing = append(missing, k)
		}
	}
	for k, reason := range paramRouteScopeAllowlist {
		if strings.TrimSpace(reason) == "" {
			t.Errorf("allowlist entry %q has no reason", k)
		}
		if !found[k] {
			stale = append(stale, k)
		}
	}
	sort.Strings(missing)
	sort.Strings(stale)
	if len(missing) > 0 {
		t.Errorf("param routes without a ForResource wrapper or allowlist entry (scope them, or allowlist with a reason):\n%s", strings.Join(missing, "\n"))
	}
	if len(stale) > 0 {
		t.Errorf("stale allowlist entries (route now scoped or removed, delete them):\n%s", strings.Join(stale, "\n"))
	}
}

